import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.kOe0DhAP.js";const h=JSON.parse('{"title":"异常处理与一致性保障","description":"用订单、成交和账务事实共同判断结果。","frontmatter":{"title":"异常处理与一致性保障","description":"用订单、成交和账务事实共同判断结果。"},"headers":[],"relativePath":"spot/exceptions.md","filePath":"spot/exceptions.md"}'),o={name:"spot/exceptions.md"};function s(i,t,n,c,l,p){return d(),a("div",null,[...t[0]||(t[0]=[r('<div class="doc-eyebrow">现货手册 / TGEX KNOWLEDGE BASE</div><h1 id="异常处理与一致性保障" tabindex="-1">异常处理与一致性保障 <a class="header-anchor" href="#异常处理与一致性保障" aria-label="Permalink to &quot;异常处理与一致性保障&quot;">​</a></h1><div class="doc-lead">用订单、成交和账务事实共同判断结果。</div><table tabindex="0"><thead><tr><th>场景</th><th>设计上应如何处理</th></tr></thead><tbody><tr><td>提交后超时</td><td>使用原业务标识查询，先确认是否受理</td></tr><tr><td>余额不足</td><td>拒绝占用，避免订单进入可成交状态</td></tr><tr><td>撤单时继续成交</td><td>按权威处理顺序确认剩余量，再解冻</td></tr><tr><td>成交消息重复</td><td>按成交唯一标识识别已处理结果</td></tr><tr><td>结算只完成部分动作</td><td>保留处理中状态与恢复任务，核对每条账务事实</td></tr><tr><td>撮合重启</td><td>恢复未完成委托及处理边界，避免重放已结算资金</td></tr></tbody></table><h2 id="检查方法" tabindex="-1">检查方法 <a class="header-anchor" href="#检查方法" aria-label="Permalink to &quot;检查方法&quot;">​</a></h2><p>沿业务编号核对委托、成交、占用、扣款与入账。只看页面余额或最后一条报错无法判断完整结果。异常修复应留下原因、审核和处理记录。</p><p>这些是应满足的设计目标。工程中可见撮合恢复、事件处理和资金相关实现，但是否覆盖所有异常需要运行测试与部署核查。</p>',7)])])}const m=e(o,[["render",s]]);export{h as __pageData,m as default};
